<script lang="ts">
  import { depositToAccount, getNetWorth, openBankAccount, transferBetweenAccounts, withdrawFromAccount, formatCharacterMoney } from './lib/simulation';
  import type { BankAccountType, Character } from './lib/types';
  import FinanceProducts from './FinanceProducts.svelte';
  let { character, onChange }: { character: Character; onChange: (next: Character) => void } = $props();
  let accountType = $state<BankAccountType>('checking');
  let fixedTermYears = $state('1');
  let accountName = $state('');
  let selectedAccount = $state('');
  let transferTarget = $state('');
  let amount = $state('100');
  let notice = $state('');
  let activeBankingView = $state<'accounts'|'cards'|'loans'|'savings'>('accounts');
  const accounts = $derived(character.bankAccounts ?? []);
  const transactions = $derived([...(character.financialTransactions ?? [])].reverse().slice(0, 8));
  const selected = $derived(accounts.find((account) => account.id === selectedAccount) ?? accounts[0]);
  function createAccount() { const next = openBankAccount(character, accountType, accountName, Number(fixedTermYears)); if (next === character) { notice = 'Account could not be opened.'; return; } onChange(next); accountName = ''; notice = 'Account opened.'; }
  function value() { const parsed = Number(amount); return Number.isFinite(parsed) ? Math.floor(parsed) : 0; }
  function deposit() { if (!selected) return; const next = depositToAccount(character, selected.id, value()); if (next === character) { notice = 'Check the amount and available cash.'; return; } onChange(next); notice = 'Deposit completed.'; }
  function withdraw() { if (!selected) return; const next = withdrawFromAccount(character, selected.id, value()); if (next === character) { notice = 'Check the amount and account balance.'; return; } onChange(next); notice = 'Withdrawal completed.'; }
  function transfer() { if (!selected) return; const target = transferTarget || accounts.find((account) => account.id !== selected.id)?.id; if (!target) { notice = 'Open another account to make a transfer.'; return; } const next = transferBetweenAccounts(character, selected.id, target, value()); if (next === character) { notice = 'Check the amount, source balance, and destination.'; return; } onChange(next); notice = 'Transfer completed.'; }
</script>
<section class="bank-panel">
  <div class="panel-heading"><div><small>FINANCIAL FOUNDATION</small><h2>Banking</h2></div><div class="net-worth"><small>NET WORTH*</small><strong>{formatCharacterMoney(character, getNetWorth(character))}</strong></div></div>
  <nav class="banking-nav" aria-label="Banking services">
    <button class:active={activeBankingView==='accounts'} onclick={() => activeBankingView='accounts'}>Accounts</button>
    <button class:active={activeBankingView==='cards'} onclick={() => activeBankingView='cards'}>Cards</button>
    <button class:active={activeBankingView==='loans'} onclick={() => activeBankingView='loans'} disabled={character.age<18}>Loans</button>
    <button class:active={activeBankingView==='savings'} onclick={() => activeBankingView='savings'}>Savings & vault</button>
  </nav>
  {#if activeBankingView === 'accounts'}
  <div class="balances"><div><small>Cash</small><strong>{formatCharacterMoney(character)}</strong></div><div><small>In accounts</small><strong>{formatCharacterMoney(character, accounts.reduce((sum, account) => sum + account.balance, 0))}</strong></div></div>
  <div class="account-list">{#if accounts.length === 0}<p class="empty">No bank accounts yet. Open an account to keep money outside your cash balance.</p>{:else}{#each accounts as account}<article class="account"><div class="account-icon">{account.type === 'savings' || account.type === 'fixed-deposit' ? '◇' : '▤'}</div><div class="account-info"><strong>{account.name}</strong><small>{account.type === 'savings' ? 'Savings · 2% annual interest' : account.type === 'fixed-deposit' ? 'Fixed deposit · 4.5% annual · matures year ' + account.maturesAtYear : 'Everyday · no interest'}</small></div><strong class="account-balance">{formatCharacterMoney(character, account.balance)}</strong></article>{/each}{/if}</div>
  <details class="account-details"><summary>Open a bank account</summary><div class="form-grid"><label>Account type<select bind:value={accountType}><option value="checking">Everyday / checking</option><option value="savings">Savings</option><option value="fixed-deposit">Fixed deposit</option></select></label><label>Account name<input bind:value={accountName} maxlength="28" placeholder={accountType === 'savings' ? 'Savings account' : 'Everyday account'} /></label></div>{#if accountType === 'fixed-deposit'}<label>Lock term (1–10 years)<input type="number" min="1" max="10" step="1" bind:value={fixedTermYears}/></label><small class="hint">Fixed deposits earn 4.5% annual interest and cannot be withdrawn before maturity.</small>{/if}<button class="primary" onclick={createAccount} disabled={character.age < 16 || accounts.length >= 8}>Open account</button>{#if character.age < 16}<small class="hint">Personal bank accounts unlock at age 16.</small>{/if}{#if accounts.length >= 8}<small class="hint">You have reached the eight-account limit.</small>{/if}</details>
  {#if accounts.length > 0}<details class="account-details"><summary>Move money</summary><label>Account<select bind:value={selectedAccount}>{#each accounts as account}<option value={account.id}>{account.name} · {formatCharacterMoney(character, account.balance)}</option>{/each}</select></label><label>Amount<input type="number" min="1" step="1" bind:value={amount} inputmode="numeric" /></label><div class="action-row"><button onclick={deposit}>Deposit cash</button><button onclick={withdraw}>Withdraw cash</button></div>{#if accounts.length > 1}<label>Transfer to<select bind:value={transferTarget}><option value="">Choose destination</option>{#each accounts.filter((account) => account.id !== (selected?.id ?? selectedAccount)) as account}<option value={account.id}>{account.name}</option>{/each}</select></label><button class="primary" onclick={transfer}>Transfer between accounts</button>{/if}<small class="hint">Transfers are immediate. You cannot withdraw or transfer more than the available balance.</small></details>{/if}
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
  <div class="transactions"><h3>Recent money activity</h3>{#if transactions.length === 0}<p class="empty">Deposits, withdrawals, transfers, income, and interest will appear here.</p>{:else}{#each transactions as transaction}<div class="transaction"><div><strong>{transaction.description}</strong><small>Age {transaction.age} · {transaction.year} · {transaction.from} → {transaction.to}</small></div><b>{transaction.amount ? formatCharacterMoney(character, transaction.amount) : '—'}</b></div>{/each}{/if}</div>
  <small class="hint">*Net worth includes cash, bank accounts, vault cash, property, investments and business value, less loans and credit-card balances. Values are simplified estimates.</small>
  {:else if activeBankingView === 'cards'}
    <FinanceProducts {character} {onChange} view="cards" />
  {:else if activeBankingView === 'loans'}
    <FinanceProducts {character} {onChange} view="loans" />
  {:else}
    <FinanceProducts {character} {onChange} view="savings" />
  {/if}
</section>
<style>
.banking-nav{display:flex;gap:6px;overflow-x:auto;padding:2px 0 10px;scrollbar-width:thin}.banking-nav button{flex:none;min-height:40px;padding:0 12px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(255,255,255,.04);color:var(--muted,#aaa);font-size:11px;font-weight:650;white-space:nowrap}.banking-nav button.active{border-color:rgba(67,211,158,.45);background:rgba(67,211,158,.1);color:var(--accent,#43d39e)}.banking-nav button:disabled{opacity:.35}.bank-panel{background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.09);border-radius:18px;padding:18px;margin:18px 0;color:var(--text,#f4f4f4)}.panel-heading,.balances,.account,.transaction{display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-heading small,.balances small,.account-info small,.hint,.transaction small,.net-worth small{display:block;color:var(--muted,#9a9a9a);font-size:11px}h2{font-size:22px;margin:4px 0 0}.net-worth{text-align:right}.net-worth strong{display:block;font-size:17px;color:var(--accent,#43d39e);margin-top:4px}.balances{margin:16px 0;padding:12px;background:rgba(255,255,255,.035);border-radius:12px}.balances strong{display:block;margin-top:4px;font-size:15px}.tax-summary{display:flex;justify-content:space-between;gap:10px;padding:9px 10px;margin:8px 0;border-radius:9px;background:rgba(255,255,255,.035);font-size:10px;color:var(--muted,#999)}.tax-summary strong{display:block;color:var(--text,#eee);font-size:12px;margin-top:3px}.account-list{display:grid;gap:8px}.account{padding:12px;border:1px solid rgba(255,255,255,.08);border-radius:12px}.account-icon{width:34px;height:34px;display:grid;place-items:center;background:rgba(67,211,158,.12);color:var(--accent,#43d39e);border-radius:10px}.account-info{flex:1;min-width:0}.account-info strong{display:block;font-size:14px}.account-balance{font-size:14px;white-space:nowrap}.account-details{border-top:1px solid rgba(255,255,255,.08);margin-top:14px;padding-top:12px}.account-details summary{cursor:pointer;font-weight:650;font-size:14px;padding:4px 0 10px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{display:grid;gap:6px;font-size:12px;color:var(--muted,#aaa);margin:8px 0}input,select{width:100%;min-width:0;padding:11px;border-radius:9px;border:1px solid rgba(255,255,255,.12);background:#171a19;color:var(--text,#f4f4f4);font:inherit}button{border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);color:var(--text,#fff);padding:10px 12px;border-radius:9px;font:inherit;font-size:12px;font-weight:650;cursor:pointer}.primary{background:var(--accent,#43d39e);color:#07150f;border:0}.action-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.hint{margin-top:8px;line-height:1.5}.notice{font-size:12px;color:var(--accent,#43d39e);margin:10px 0 0}.empty{color:var(--muted,#999);font-size:12px;line-height:1.5;margin:8px 0}.transactions{border-top:1px solid rgba(255,255,255,.08);margin-top:16px;padding-top:12px}.transactions h3{font-size:14px;margin:0 0 8px}.transaction{padding:9px 0;border-bottom:1px solid rgba(255,255,255,.05)}.transaction div{min-width:0}.transaction strong{display:block;font-size:12px;line-height:1.4}.transaction small{margin-top:3px;overflow-wrap:anywhere}.transaction b{font-size:12px;white-space:nowrap}@media(max-width:480px){.bank-panel{padding:13px}.form-grid{grid-template-columns:1fr}.panel-heading{align-items:flex-start}}
</style>